import os, pathlib, json
for k in ['STAMPED_ASSESSMENT_VERSION','STAMPED_DELIVERY_MANIFEST','STAMPED_OPERATIONAL_MANIFEST','STAMPED_WORKER_STOP_RECEIPT','STAMPED_SCIENTIFIC_JUDGMENT_VALIDATOR']:
 p=os.environ.get(k)
 print('\n###',k,p)
 if p and pathlib.Path(p).exists():
  print(pathlib.Path(p).read_text())
PY
rg --files "$STAMPED_JUDGE_TARGET" | sed -n '1,200p'
","yield_time_ms":10000,"max_output_tokens":8000});
text(r.output);

