import hashlib, json, os, pathlib, stat
manifest = json.load(open(os.environ['STAMPED_OPERATIONAL_MANIFEST']))
root = pathlib.Path(os.environ['STAMPED_JUDGE_TARGET'])
expected = {}
for e in manifest['entries']:
    p=e['path']
    if p == 'content/workspace': rel='.'
    elif p.startswith('content/workspace/'): rel=p[len('content/workspace/'):]
    else: continue
    expected[rel]=e
actual={}
for base, dirs, files in os.walk(root, topdown=True, followlinks=False):
    b=pathlib.Path(base)
    for name in list(dirs):
        p=b/name; rel=p.relative_to(root).as_posix()
        if p.is_symlink():
            dirs.remove(name)
            actual[rel]=p
        else: actual[rel]=p
    for name in files:
        p=b/name; actual[p.relative_to(root).as_posix()]=p
actual['.']=root
mismatches=[]
for rel in sorted(set(expected)|set(actual)):
    e=expected.get(rel); p=actual.get(rel)
    if e is None: mismatches.append({'path':rel,'issue':'unexpected'}); continue
    if p is None: mismatches.append({'path':rel,'issue':'missing'}); continue
    st=p.lstat(); mode=stat.S_IMODE(st.st_mode)
    if mode != e.get('mode'): mismatches.append({'path':rel,'issue':'mode','expected':e.get('mode'),'actual':mode})
    if p.is_symlink():
        kind='symlink'; target=os.readlink(p); digest=hashlib.sha256(os.fsencode(target)).hexdigest(); size=len(os.fsencode(target))
    elif p.is_dir(): kind='directory'; digest=None; size=None
    elif p.is_file():
        kind='file'; h=hashlib.sha256()
        with p.open('rb') as f:
            for chunk in iter(lambda:f.read(1024*1024),b''): h.update(chunk)
        digest=h.hexdigest(); size=st.st_size
    else: kind='other'; digest=None; size=st.st_size
    if kind != e.get('kind'): mismatches.append({'path':rel,'issue':'kind','expected':e.get('kind'),'actual':kind})
    if 'sha256' in e and digest != e['sha256']: mismatches.append({'path':rel,'issue':'sha256','expected':e['sha256'],'actual':digest})
    if 'size' in e and size != e['size']: mismatches.append({'path':rel,'issue':'size','expected':e['size'],'actual':size})
exempt=[]; integrity=[]
for m in mismatches:
    if m['path'] in ('.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal') and m['issue'] in ('sha256','size'):
        exempt.append(m)
    else: integrity.append(m)
result={'capture_sha256':hashlib.sha256(open(os.environ['STAMPED_DELIVERY_MANIFEST'],'rb').read()).hexdigest(), 'expected_entries':len(expected),'actual_entries':len(actual),'mismatch_count':len(mismatches),'integrity_invalidating_mismatches':integrity,'operational_metadata_mismatches':exempt}
out=pathlib.Path(os.environ['STAMPED_JUDGE_OUTPUT'])/'integrity-audit.json'; out.write_text(json.dumps(result,indent=2)+'\n'); print(json.dumps(result,indent=2))
